from common import *
from phase2_temporal import ema
import pandas as pd,hashlib
O=ROOT/"phase129";pr=json.loads((O/"protocol.json").read_text());assert hashlib.sha256((O/"protocol.json").read_bytes()).hexdigest()==(O/"protocol.sha256").read_text().strip();audit=json.loads((O/"audit.json").read_text());assert audit["status"]=="PASS"
shapepr=json.loads((ROOT/"phase100/protocol.json").read_text());assert pr["shape_reference_sha256"]==shapepr["reference_sha256"];input_checks=[];rows=[];max_f1_error=0.
for rec in audit["records"]:
 c=rec["case"];name="_".join(c[k] for k in ["domain","subject","montage"]);mode=rec["mode"];path=O/"predictions"/f"{name}_{mode}.npz";assert hashlib.sha256(path.read_bytes()).hexdigest()==rec["prediction_sha256"];bp=Path(rec["baseline_path"]);assert hashlib.sha256(bp.read_bytes()).hexdigest()==rec["baseline_sha256"]
 if mode=="full":
  old=json.loads((ROOT/"phase100/predictions"/f"{name}_audit.json").read_text());scalar=Path(old["baseline_path"]);gp=scalar.with_name(scalar.stem+"_normalizer.npz");gainsha=hashlib.sha256(gp.read_bytes()).hexdigest();assert gainsha==old["gains_sha256"];input_checks.append(dict(case=name,gain_cache_matches_original_shape_run=True,gains_sha256=gainsha))
 base=np.load(bp);aug=np.load(path);loaded=np.load(c["labels"]);y=loaded["y"] if c["labels"].endswith(".npz") else loaded
 for seed in [17,29,43]:
  for variant,p in dict(repeat=base[f"cbramod_seed{seed}"],augmented=aug[f"amplitude_augmented_seed{seed}"]).items():
   for alpha in [1.,.8,.5]:
    q=p if alpha==1 else ema(p,alpha);met=metrics(y,q);cm=np.array(met["confusion"]);den=cm.sum(0)+cm.sum(1);f1=np.divide(2*np.diag(cm),den,out=np.zeros(5),where=den>0);err=abs(f1.mean()-met["macro_f1"]);assert err<1e-12;max_f1_error=max(max_f1_error,float(err));rows.append(dict(domain=c["domain"],subject=c["subject"],montage=c["montage"],mode=mode,variant=variant,seed=seed,ema=alpha,macro_f1=100*met["macro_f1"],balanced_accuracy=100*met["balanced_accuracy"],ce=met["ce"]))
df=pd.DataFrame(rows);assert len(df)==3312;df.to_csv(O/"participants.csv",index=False);keys=["domain","subject","montage","mode","variant","ema"];person=df.groupby(keys)[["macro_f1","balanced_accuracy","ce"]].mean().reset_index();person.to_csv(O/"people.csv",index=False);summary=person.groupby(["domain","montage","mode","variant","ema"])[["macro_f1","balanced_accuracy","ce"]].mean().reset_index();summary.to_csv(O/"summary.csv",index=False)
person["cell"]=person.variant+"_"+person["mode"];comparisons=[]
for (domain,montage,alpha),g in person.groupby(["domain","montage","ema"]):
 tab=g.pivot(index="subject",columns="cell",values="macro_f1");rng=np.random.default_rng(129017);ix=rng.integers(0,len(tab),(10000,len(tab)))
 for new,old,label in [("augmented_full","repeat_full","augmentation_with_fullshape"),("augmented_raw","repeat_raw","augmentation_raw"),("augmented_full","augmented_raw","fullshape_with_augmentation"),("repeat_full","repeat_raw","fullshape_original"),("augmented_full","repeat_raw","combined_vs_original_raw")]:
  d=tab[new]-tab[old];ci=np.quantile(d.to_numpy()[ix].mean(1),[.025,.975]);comparisons.append(dict(domain=domain,montage=montage,ema=alpha,comparison=label,people=len(d),new_f1=float(tab[new].mean()),old_f1=float(tab[old].mean()),difference_pp=float(d.mean()),ci_low=float(ci[0]),ci_high=float(ci[1]),positive_people=int((d>0).sum()),harm_over1pp=int((d < -1).sum()),worst_pp=float(d.min())))
 d=(tab.augmented_full-tab.augmented_raw)-(tab.repeat_full-tab.repeat_raw);ci=np.quantile(d.to_numpy()[ix].mean(1),[.025,.975]);comparisons.append(dict(domain=domain,montage=montage,ema=alpha,comparison="factorial_interaction",people=len(d),new_f1=np.nan,old_f1=np.nan,difference_pp=float(d.mean()),ci_low=float(ci[0]),ci_high=float(ci[1]),positive_people=int((d>0).sum()),harm_over1pp=int((d < -1).sum()),worst_pp=float(d.min())))
comp=pd.DataFrame(comparisons);comp.to_csv(O/"comparisons.csv",index=False);primary=comp[(comp.domain=="patient")&(comp.montage=="left")&(comp.ema==.5)&(comp.comparison=="augmentation_with_fullshape")];assert len(primary)==1;primary.to_csv(O/"primary.csv",index=False)
sa=dict(status="PASS",streams=len(df),independent_macro_f1_error=max_f1_error,old_input_gain_caches_verified=len(input_checks),reference_shape_unchanged=True,seed29_fallback_retained=True,all_source_selected_checkpoints_retained=True,within_person_seed_metric_means=True,not_blind=True,no_new_training_or_updates=True)
(O/"summary_audit.json").write_text(json.dumps(sa,indent=2));(O/"input_cache_audit.json").write_text(json.dumps(input_checks,indent=2));show=comp[(comp.ema==.5)&comp.montage.isin(["native","left"])]
(O/"report.html").write_text('<!doctype html><meta charset="utf-8"><style>body{font:16px/1.6 sans-serif;max-width:1400px;margin:35px auto}td,th{padding:6px;border:1px solid #ddd}</style><h1>既有幅值增强与既有输入校准的固定组合</h1><p>固定2×2：原源选择重复训练模型/幅值增强模型 × 原始输入/既有完整幅值及通道形状校准。种子17/29/43增强所选轮次3/0/3，原重复分支均0；种子29回退保留且直接复用相同模型预测。没有新训练、目标选模或阈值调整。</p><h2>预定探索性主比较：既有患者19人、左侧、EMA0.5</h2>'+primary.to_html(index=False,float_format=lambda v:f"{v:.6f}")+'<h2>四格绝对结果</h2>'+summary[(summary.ema==.5)&summary.montage.isin(["native","left"])].to_html(index=False,float_format=lambda v:f"{v:.6f}")+'<h2>成对差异和描述性交互</h2>'+show.to_html(index=False,float_format=lambda v:f"{v:.6f}")+'<p>交互=(增强模型的校准增益)-(原模型的校准增益)，只描述这四个固定条件下Macro-F1的非加性，不是临床因果效应。完整校准同时包含幅值和通道形状处理，不能将差异单独归因于一个成分。每人先平均种子指标，再配对按人计算区间。</p><p>所有目标此前已观察。原始增强预测与phase95/97分类一致；重复模型逐元素等同原父模型；校准增益缓存SHA与phase100一致。没有梯度TTT或部署。<a href="protocol.json">固定组合协议</a> · <a href="summary_audit.json">统计审计</a> · <a href="input_cache_audit.json">输入缓存复核</a></p>')
